# 暴力验证小例子: n=3, r=2, b=1
# 红={1,2}, 蓝={3}
n = 3
red = {1, 2}
count = 0
for x in range(1, n+1):
    for y in range(1, n+1):
        for z in range(1, n+1):
            if (x + y + z) % n == 0:
                if (x in red and y in red and z in red) or (x not in red and y not in red and z not in red):
                    count += 1
print(f"n=3, r=2, b=1: 暴力计数={count}, 公式={ (2**3 + 1**3) // 3 }")

# 再验证 n=6, r=4, b=2
n = 6
red = {1, 2, 3, 4}
count = 0
for x in range(1, n+1):
    for y in range(1, n+1):
        for z in range(1, n+1):
            if (x + y + z) % n == 0:
                if (x in red and y in red and z in red) or (x not in red and y not in red and z not in red):
                    count += 1
r, b = 4, 2
print(f"n=6, r=4, b=2: 暴力计数={count}, 公式={ (r**3 + b**3) // n } = {r**2 - r*b + b**2}")

# 验证 n=69 的一个随机着色
import random
random.seed(42)
n = 69
red_set = set(random.sample(range(1, n+1), 51))
count = 0
for x in range(1, n+1):
    xr = x in red_set
    for y in range(1, n+1):
        yr = y in red_set
        # z 使得 x+y+z ≡ 0 mod n, z = n - (x+y)%n, 但要映射到 1..n
        z_mod = (-(x + y)) % n  # 0..n-1
        z = z_mod if z_mod != 0 else n  # 映射到 1..n
        zr = z in red_set
        if (xr and yr and zr) or (not xr and not yr and not zr):
            count += 1
print(f"n=69, r=51, b=18: 暴力计数={count}, 公式={51**2 - 51*18 + 18**2}")
EOF
